import React, { useEffect, useState } from "react";
import {
  MapContainer,
  TileLayer,
  CircleMarker,
  Popup,
  Circle,
  useMap,
} from "react-leaflet";
import "leaflet/dist/leaflet.css";

// Componente para cambiar la vista del mapa al seleccionar un sismo
const ChangeView = ({ coordenadas }) => {
  const map = useMap();
  useEffect(() => {
    if (coordenadas) {
      map.setView([coordenadas.lat, coordenadas.lng], 7);
    }
  }, [coordenadas, map]);
  return null;
};

const MapaMexico = ({ coordenadas, theme, placas, loadingPlacas, errorPlacas }) => {
  const [circleScale, setCircleScale] = useState(1);
  const [opacity, setOpacity] = useState(0.6);

  // 👈 AGREGAR ESTE EFECTO PARA DEBUG
  useEffect(() => {
    console.log("=== DEBUG PLACAS EN MAPA ===");
    console.log("Placas recibidas:", placas);
    console.log("Tipo de placas:", typeof placas);
    console.log("Es array:", Array.isArray(placas));
    console.log("Cantidad de placas:", placas?.length);
    
    if (placas && placas.length > 0) {
      console.log("Estructura de primera placa:", placas[0]);
      console.log("Geometría de primera placa:", placas[0]?.geometry);
      console.log("Coordenadas de primera placa:", placas[0]?.geometry?.coordinates);
    }
  }, [placas]);

  // Validar placas con más detalle
  const placasValidas = useMemo(() => {
    console.log("=== VALIDANDO PLACAS ===");
    
    if (!Array.isArray(placas)) {
      console.warn("Placas no es un array:", placas);
      return [];
    }
    
    const validas = placas.filter((placa, index) => {
      console.log(`Validando placa ${index}:`, placa);
      
      // Validar estructura GeoJSON básica
      if (!placa || typeof placa !== 'object') {
        console.warn(`❌ Placa ${index} no es un objeto válido:`, placa);
        return false;
      }
      
      if (!placa.type || placa.type !== 'Feature') {
        console.warn(`❌ Placa ${index} no tiene type 'Feature':`, placa.type);
        return false;
      }
      
      if (!placa.geometry) {
        console.warn(`❌ Placa ${index} no tiene geometry:`, placa);
        return false;
      }
      
      if (!placa.geometry.coordinates) {
        console.warn(`❌ Placa ${index} no tiene coordinates:`, placa.geometry);
        return false;
      }
      
      if (!Array.isArray(placa.geometry.coordinates)) {
        console.warn(`❌ Placa ${index} coordinates no es array:`, placa.geometry.coordinates);
        return false;
      }
      
      // Validar que las coordenadas no tengan NaN
      const hasNaN = JSON.stringify(placa.geometry.coordinates).includes('null') || 
                    JSON.stringify(placa.geometry.coordinates).includes('NaN');
      
      if (hasNaN) {
        console.warn(`❌ Placa ${index} tiene coordenadas NaN/null:`, placa.geometry.coordinates);
        return false;
      }
      
      console.log(`✅ Placa ${index} es válida:`, placa.properties?.nombre);
      return true;
    });
    
    console.log(`Total placas válidas: ${validas.length} de ${placas.length}`);
    return validas;
  }, [placas]);

  // Resto de tu código...
  const onEachFeature = (feature, layer) => {
    console.log("Configurando feature:", feature.properties?.nombre);
    
    if (feature.properties) {
      const popupContent = `
        <div style="min-width: 200px;">
          <h3 style="margin: 0 0 10px 0; color: #333;">
            ${feature.properties.nombre || 'Placa Tectónica'}
          </h3>
          <p style="margin: 0; font-size: 14px;">
            ${feature.properties.descripcion || 'Sin descripción disponible'}
          </p>
          ${feature.properties.id ? `<p style="margin: 5px 0 0 0; font-size: 12px; color: #666;">ID: ${feature.properties.id}</p>` : ''}
        </div>
      `;
      layer.bindPopup(popupContent);
    }

    layer.on({
      mouseover: (e) => {
        console.log("Hover sobre placa:", feature.properties?.nombre);
        const layer = e.target;
        layer.setStyle({
          color: "#ff7800",
          weight: 3,
          opacity: 1,
          fillOpacity: 0.3
        });
      },
      mouseout: (e) => {
        const layer = e.target;
        layer.setStyle({
          color: "#3388ff",
          weight: 2,
          opacity: 0.8,
          fillOpacity: 0.1,
          fillColor: "#3388ff"
        });
      }
    });
  };

  return (
    <div style={{ position: 'relative', height: '100%', width: '100%' }}>
      {/* Debug info en el mapa */}
      <div style={{
        position: 'absolute',
        top: '10px',
        left: '10px',
        background: 'rgba(255,255,255,0.9)',
        padding: '10px',
        borderRadius: '5px',
        zIndex: 1000,
        fontSize: '12px'
      }}>
        <div>Placas totales: {placas?.length || 0}</div>
        <div>Placas válidas: {placasValidas?.length || 0}</div>
        <div>Estado: {loadingPlacas ? 'Cargando...' : 'Listo'}</div>
        {errorPlacas && <div style={{color: 'red'}}>Error: {errorPlacas}</div>}
      </div>

      <MapContainer
        center={[23.6345, -102.5528]}
        zoom={5}
        style={{ height: "100%", width: "100%" }}
      >
        <TileLayer 
          url={theme === "dark"
            ? "https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png"
            : "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"}
          attribution={theme === "dark"
            ? '&copy; <a href="https://carto.com/">CARTO</a>'
            : '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}
        />

        {/* Renderizar placas con más logs */}
        {placasValidas && placasValidas.map((feature, idx) => {
          console.log(`Intentando renderizar placa ${idx}:`, feature.properties?.nombre);
          
          try {
            return (
              <GeoJSON
                key={`placa-${feature.properties?.id || idx}-${Date.now()}`}
                data={feature}
                style={{
                  color: "#ff0000", // 👈 Color rojo para que se vea bien
                  weight: 3,
                  opacity: 1,
                  fillOpacity: 0.2,
                  fillColor: "#ff0000"
                }}
                onEachFeature={onEachFeature}
              />
            );
          } catch (error) {
            console.error(`❌ Error renderizando placa ${idx}:`, error);
            console.error("Datos de la placa:", feature);
            return null;
          }
        })}

        <ChangeView coordenadas={coordenadas} />
        
        {/* Tu código de sismos */}
        {coordenadas && (
          <>
            <CircleMarker
              center={[coordenadas.lat, coordenadas.lng]}
              radius={10}
              color="blue"
              fillColor="blue"
              fillOpacity={0.7}
            >
              <Popup>
                <b>Ubicación del Sismo</b> <br />
                Lat: {coordenadas.lat}, Lng: {coordenadas.lng}
              </Popup>
            </CircleMarker>
          </>
        )}
      </MapContainer>
    </div>
  );
};
export default MapaMexico;
